import http from 'node:http';
const rute = { 'POST /x': (req, res) => { res.statusCode = 201; res.end(); } };
const s = http.createServer((req, res) => {
  const p = rute[`${req.method} ${req.url}`];
  if (p) return p(req, res);
  res.statusCode = 404;
  res.end();
});
s.listen(3000);
console.log((await fetch('http://localhost:3000/x', { method: 'POST' })).status);
s.close();
